var initial = notebook.state;
var x = initial?.x ?? 2;
var pending = Promise.resolve();
var paused = false;
var button = document.querySelector("#next");
var output = document.querySelector("#value");
var point = document.querySelector("#point");
document.querySelector("#curve").setAttribute("href", curve_default);
var worker = new Worker(new URL("./worker-square.js", import.meta.url), { type: "module" });
function draw(commit = false) {
  button.disabled = true;
  return pending = new Promise((resolve, reject) => {
    worker.onerror = (event) => reject(new Error(event.message));
    worker.onmessage = (event) => {
      const y = event.data, [cx, cy] = position(x, y);
      point.setAttribute("cx", String(cx));
      point.setAttribute("cy", String(cy));
      output.textContent = `${x < 0 ? `(\u2212${-x})` : x}\xB2 = ${y}`;
      button.disabled = paused;
      if (commit) notebook.commit({ x });
      resolve();
    };
    worker.postMessage(x);
  });
}
button.onclick = () => {
  x = x >= 3 ? -3 : x + 1;
  void draw(true);
};
addEventListener("notebookstate", () => {
  x = notebook.state.x;
  void draw();
});
notebook.lifecycle({
  pause: async () => {
    paused = true;
    button.disabled = true;
    await pending;
  },
  checkpoint: () => ({ x }),
  resume: () => {
    paused = false;
    button.disabled = false;
  },
  dispose: () => worker.terminate()
});
notebook.ready(draw());
notebook.exportFrame(async ({ format, state }) => {
